WITH enriched AS (SELECT id, brand, price, cost, launch_date, tags, supplier_id, LAST_VALUE(brand, TRUE) OVER w_recent AS last_known_brand, RANK() OVER (PARTITION BY supplier_id ORDER BY stock_qty DESC) AS stock_qty_rank, SUM(price) OVER (PARTITION BY brand ORDER BY price, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_price FROM products WINDOW w_recent AS (ORDER BY price, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)) SELECT id, brand, cost, tags, last_known_brand, stock_qty_rank, cumulative_price, CASE WHEN brand RLIKE '^(Globex|Umbrella)$' THEN 'GROUP_B' WHEN brand RLIKE '^(Acme|Initech)$' THEN 'EXTENDED' ELSE 'PRIORITY' END AS brand_zone FROM enriched ORDER BY id DESC, cost;
